contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public payable {
        require(true);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balAfter = address(c).balance;
        assert(reverted && balAfter == balBefore && balAfter == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient == address(c));
        uint balBefore = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && !c._locked() && address(c).balance == balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        uint balBefore = address(this).balance;
        // No rewards have been accrued for address(this), so this call sends 0 wei.
        c.withdrawReward(address(this));
        assert(address(this).balance == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address payable recipient) public payable {
        require(address(c).balance >= 100);
        uint recipientBefore = recipient.balance;
        c.getFirstWithdrawalBonus(recipient);
        assert(recipient.balance == recipientBefore + 100);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient) public {
        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && !c._locked());
    }
    receive() external payable {}
}
